The three points $(3,-5)$, $(-a + 2, 3)$, and $(2a+3,2)$ lie on the same line.  What is $a$?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1 = 3, y1 = -5;
    double x2 = -a + 2, y2 = 3;
    double x3 = 2*a + 3, y3 = 2;

    // Calculate the slope of the line passing through points (x1, y1) and (x2, y2)
    double slope1 = (y2 - y1) / (x2 - x1);

    // Calculate the slope of the line passing through points (x1, y1) and (x3, y3)
    double slope2 = (y3 - y1) / (x3 - x1);

    // If the slopes are equal, the points lie on the same line
    if (slope1 == slope2) {
        // Calculate the value of a
        double a = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        a /= (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        cout << "The value of a is: " << a << endl;
    } else {
        cout << "The points do not lie on the same line." << endl;
    }

    return 0;
}

