  for (int i = 0; i <= n; i++) {
    for (int j = 0; j <= n; j++) {
      if (i + j == n && i >= k && j >= k) {
        result++;
      }
    }
  }

  cout << "The number of ways to choose a pair of socks is: " << result << endl;

  return 0;
}

